SELECT SUM(ss_net_paid) / COUNT(DISTINCT ss_ticket_number) AS average_order_value
FROM msb_store_sales
WHERE d_year = 2000;

SELECT SUM(ss_net_profit) / NULLIF(SUM(ss_net_paid), 0) AS margin_rate
FROM msb_store_sales
WHERE d_year = 2000;

SELECT returns.return_amt / sales.sales_amt AS store_return_rate
FROM (SELECT SUM(sr_return_amt) AS return_amt FROM msb_store_returns WHERE d_date >= DATE '2001-01-01' AND d_date < DATE '2002-01-01') AS returns
CROSS JOIN (SELECT SUM(ss_ext_sales_price) AS sales_amt FROM msb_store_sales WHERE d_date >= DATE '2001-01-01' AND d_date < DATE '2002-01-01') AS sales;
